import{_ as o,l as i,o as e,c as s,v as t,p as l,x as r,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"区间树","description":"","frontmatter":{"title":"区间树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/interval-tree.md","filePath":"cs/interval-tree.md","lastUpdated":1789023840000}'),h={name:"cs/interval-tree.md"};function c(E,a,_,B,b,T){const n=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="区间树" tabindex="-1">区间树 <a class="header-anchor" href="#区间树" aria-label="Permalink to &quot;区间树&quot;">​</a></h1><div class="epigraph"><p>按区间中点（或左端）建 BST，节点记下子树右端最大值；stabbing 一条查询线时，用最大值剪枝。</p><footer>—— 据 Preparata and Shamos, Computational Geometry；Cormen, Leiserson, Rivest and Stein 第 14.3 节；de Berg et al. 整理</footer></div><p><a href="/cs/y-fast-trie">上一课</a> 回答整数点的前驱后继。现在对象是闭区间 \\([l,r]\\)，询问「哪些区间包含点 \\(q\\)」或「与 \\([a,b]\\) 相交」。本课不把 vEB 当几何。缺口是区间树（interval tree）：与线段树同名易混，这里是<strong>一组区间对象</strong>的字典，不是下标对半。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个区间，点查询 \\(q\\)。暴力 \\(\\Theta(n)\\)。区间树：以左端（或中点）为 BST 键；每个节点额外存<strong>该子树所有区间的最大右端</strong>。查询：若 \\(q\\) 在当前区间内则报告；若左子树 \\(\\mathrm{maxR}\\ge q\\) 则必须进左，否则只进右（因为左端有序，左边左端更小，若最大右端仍 \\(\\lt q\\) 则左边全错过 \\(q\\)）。缺口是<strong>用 maxR 把 BST 查找变成 stabbing</strong>。</p><p><span class="marginnote">CLRS 14.3 用红黑存区间并维护 max。几何书里还有 segment tree（下标/扫描线另一套），名称不要混用本课课名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入删除：BST + 沿路径更新 maxR，平衡与<a href="/cs/order-statistic-tree">顺序统计</a> 维护 size 同模式。报告所有命中最坏 \\(\\Theta(n)\\)（全中）；时间 \\(O(\\log n+k)\\)。只问是否存在相交，可提前停。</p>',8)),(e(),l(m,null,{default:r(()=>[p(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%82%B9%20q%22%5D%20--%3E%20NODE%5B%22%E5%BD%93%E5%89%8D%E5%8C%BA%E9%97%B4%22%5D%0A%20%20NODE%20--%3E%20HIT%5B%22q%20%E8%90%BD%E5%9C%A8%20%5Bl%2Cr%5D%20%E5%88%99%E6%8A%A5%E5%91%8A%22%5D%0A%20%20NODE%20--%3E%20LMAX%5B%22%E5%B7%A6%20maxR%20%3E%3D%20q%3A%20%E5%BF%85%E9%A1%BB%E8%BF%9B%E5%B7%A6%22%5D%0A%20%20NODE%20--%3E%20RGO%5B%22%E5%90%A6%E5%88%99%E5%90%91%E5%8F%B3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 Fenwick/线段树：那些是数组下标上的聚合；本课每个元素自己是一段 \\([l,r]\\)。一维 stabbing 不要用 k-d 树。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正确性依赖左端子树键 \\(\\le\\) 当前 \\(\\le\\) 右，以及 maxR 真实。旋转必须修 maxR。坐标若很大可离散化，结构不依赖 vEB。</p><p>重叠极大时 \\(k\\) 大，输出瓶颈，结构帮不上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写区间树套动态树、或三维。正交矩形范围查询下一课 k-d 树与后课 R 树。点集矩形查询与区间 stabbing 选错结构会多一个 \\(\\log\\)。</p><p>后课默认：一维区间包含用区间树。平面点的正交范围用 k-d 树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>区间树：BST（左端）+ 子树 maxR，stabbing \\(O(\\log n+k)\\)。</li><li>与下标线段树不是同一结构。</li><li>平面点范围查询交给 k-d 树。</li><li>出处：Preparata and Shamos；Cormen et al. 14.3。</li></ul>',9))])}const g=o(h,[["render",c]]);export{f as __pageData,g as default};
